def tokenize(expr):
    toks=[]; pos=0; n=len(expr)
    while pos<n:
        m=TOK.match(expr,pos)
        if not m:
            # skip unknown char
            pos+=1; continue
        pos=m.end()
        if m.lastgroup=='num':
            t=m.group('num')
            if "'" in t:
                base=16 if t.split("'")[1][0].lower()=='h' else 2
                toks.append(('num',int(t.split("'")[1][1:],base)))
            else:
                toks.append(('num',int(t)))
        elif m.lastgroup=='esc':
            toks.append(('id',m.group('esc')))
        elif m.lastgroup=='id':
            toks.append(('id',m.group('id')))
        else:
            toks.append(('op',m.group('op')))
    return toks

class ExprParser:
    def __init__(self,tokens,res):
        self.t=tokens; self.i=0; self.res=res
    def peek(self):
        return self.t[self.i] if self.i<len(self.t) else (None,None)
    def take(self):
        v=self.t[self.i]; self.i+=1; return v
    def parse(self):
        return self.ternary()
    def ternary(self):
        c=self.orexpr()
        if self.peek()==('op','?'):
            self.take(); a=self.ternary()
            assert self.take()==('op',':')
            b=self.ternary()
            return a if c&1 else b
        return c&1
    def orexpr(self):
        v=self.xorexpr()
        while self.peek()==('op','|'):
            self.take(); v=(v|self.xorexpr())&1
        return v
    def xorexpr(self):
        v=self.andexpr()
        while self.peek()==('op','^'):
            self.take(); v=(v^self.andexpr())&1
        return v
    def andexpr(self):
        v=self.unary()
        while self.peek()==('op','&'):
            self.take(); v=(v&self.unary())&1
        return v
    def unary(self):
        if self.peek()==('op','~'):
            self.take(); return 1^(self.unary()&1)
        if self.peek()==('op','('):
            self.take(); v=self.ternary()
            assert self.take()==('op',')')
            return v&1
        k,val=self.take()
        if k=='num': return val&1
        if k=='id': return self.res(val)&1
        raise RuntimeError('bad token %r'%(k,val))

